/*\n  # Create Organizations Table - Multi-Tenancy Foundation\n\n  1. New Tables\n    - `organizations` - core tenant table with all org settings\n    - `organization_secrets` - sensitive API credentials (service-role only)\n\n  2. Security\n    - RLS enabled on both tables\n    - Organizations: public slug resolution for login page\n    - Organization secrets: completely locked down (service role only)\n\n  3. Data Migration\n    - Existing company_settings migrated to first organization (slug: electronic-life)\n*/\n\nCREATE TABLE IF NOT EXISTS organizations (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  name text NOT NULL,\n  slug text NOT NULL UNIQUE,\n  logo_url text,\n  website text,\n  phone text,\n  address text,\n  primary_contact_email text,\n  portal_url text,\n  timezone text NOT NULL DEFAULT 'America/New_York',\n  currency text NOT NULL DEFAULT 'USD',\n  is_active boolean NOT NULL DEFAULT true,\n  plan_tier text NOT NULL DEFAULT 'professional',\n  owner_user_id uuid,\n  from_email text,\n  from_name text,\n  reply_to_email text,\n  default_tax_rate numeric DEFAULT 9.35,\n  default_invoice_terms text DEFAULT 'Net 30',\n  default_deposit_percent numeric DEFAULT 50,\n  default_project_mgmt_percent numeric DEFAULT 0,\n  default_system_design_percent numeric DEFAULT 0,\n  default_cc_fee_percent numeric DEFAULT 3,\n  default_misc_parts_percent numeric DEFAULT 0,\n  cc_convenience_fee_enabled boolean DEFAULT false,\n  cc_convenience_fee_type text DEFAULT 'percentage',\n  cc_convenience_fee_percentage numeric DEFAULT 0.03,\n  cc_convenience_fee_flat_amount numeric DEFAULT 3.00,\n  cc_convenience_fee_label text DEFAULT 'Credit Card Convenience Fee',\n  commission_settings jsonb DEFAULT '{"pm_rate": 1.0, "sales_rate": 5.0, "design_rate": 2.5, "service_rate": 3.0}'::jsonb,\n  job_module_enabled boolean DEFAULT false,\n  job_module_settings jsonb DEFAULT '{"tax_rate": 0.08, "invoice_terms": "Net 30", "commission_defaults": {"basis": "gross", "rates": {"designer": 0.02, "installer": 0.02, "sales_rep": 0.05, "project_manager": 0.03}}, "deposit_default_percent": 0.50}'::jsonb,\n  auto_clock_out_enabled boolean DEFAULT true,\n  forgot_clock_out_penalty_points integer DEFAULT -15,\n  business_day_end_time time DEFAULT '18:00:00',\n  auto_clock_out_cutoff_time time DEFAULT '22:00:00',\n  auto_clock_out_schedule_enabled boolean DEFAULT false,\n  last_auto_clock_out_run timestamptz,\n  require_gps_for_clock_in boolean DEFAULT true,\n  require_gps_for_clock_out boolean DEFAULT true,\n  home_clock_notification_enabled boolean DEFAULT true,\n  home_location_radius_meters integer DEFAULT 100,\n  home_clock_notification_roles text[] DEFAULT ARRAY['admin', 'office_manager', 'production_manager', 'service_manager'],\n  photo_upload_points integer NOT NULL DEFAULT 1,\n  on_my_way_sms_template text DEFAULT 'Hi {customer_name}, this is {tech_name} from your service provider. I''m on my way to your location for work order {job_number}. I should arrive soon. Thank you!',\n  global_minimum_margin numeric DEFAULT 0,\n  enforce_minimum_pricing boolean DEFAULT false,\n  labor_rate_per_hour numeric DEFAULT 100,\n  portal_proposals_enabled boolean DEFAULT true,\n  portal_projects_enabled boolean DEFAULT false,\n  portal_appointments_enabled boolean DEFAULT false,\n  portal_invoices_enabled boolean DEFAULT false,\n  portal_messages_enabled boolean DEFAULT false,\n  portal_vip_services_enabled boolean DEFAULT false,\n  portal_punchlist_enabled boolean DEFAULT true,\n  enable_public_vip_signup boolean DEFAULT false,\n  auto_completion_enabled boolean DEFAULT true,\n  auto_completion_requires_approval boolean DEFAULT false,\n  auto_completion_reopen_on_delete boolean DEFAULT true,\n  auto_archive_declined_proposals_enabled boolean DEFAULT true,\n  auto_archive_declined_after_days integer DEFAULT 90,\n  created_at timestamptz DEFAULT now(),\n  updated_at timestamptz DEFAULT now()\n)

\n\nCREATE TABLE IF NOT EXISTS organization_secrets (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,\n  qbo_connected boolean DEFAULT false,\n  qbo_realm_id text,\n  qbo_access_token text,\n  qbo_refresh_token text,\n  qbo_token_expires_at timestamptz,\n  qbo_payments_enabled boolean DEFAULT false,\n  twilio_account_sid text,\n  twilio_auth_token text,\n  twilio_phone_number text,\n  google_maps_api_key text,\n  zip_tax_api_key text,\n  gemini_api_key text,\n  openai_api_key text,\n  portal_io_connected boolean DEFAULT false,\n  portal_io_access_token text,\n  portal_io_token_expires_at timestamptz,\n  created_at timestamptz DEFAULT now(),\n  updated_at timestamptz DEFAULT now(),\n  CONSTRAINT organization_secrets_org_unique UNIQUE (organization_id)\n)

\n\nCREATE INDEX IF NOT EXISTS idx_organizations_slug ON organizations(slug)

\nCREATE INDEX IF NOT EXISTS idx_organizations_is_active ON organizations(is_active)

\nCREATE INDEX IF NOT EXISTS idx_organization_secrets_org_id ON organization_secrets(organization_id)

\n\nALTER TABLE organizations ENABLE ROW LEVEL SECURITY

\nALTER TABLE organization_secrets ENABLE ROW LEVEL SECURITY

\n\n-- Public read for tenant resolution (login page needs slug -> org lookup)\nCREATE POLICY "Anyone can read active org info"\n  ON organizations\n  FOR SELECT\n  TO anon, authenticated\n  USING (is_active = true)

\n\n-- No policies on organization_secrets = completely locked for client access\n\n-- Migrate existing company_settings\nDO $$\nDECLARE\n  v_cs RECORD

\n  v_org_id uuid

\nBEGIN\n  SELECT * INTO v_cs FROM company_settings LIMIT 1

\n  IF v_cs IS NOT NULL THEN\n    v_org_id := gen_random_uuid()

\n    INSERT INTO organizations (\n      id, name, slug, logo_url, website, phone, address,\n      primary_contact_email, portal_url, timezone, currency,\n      from_email, from_name, reply_to_email,\n      default_tax_rate, default_invoice_terms, default_deposit_percent,\n      default_project_mgmt_percent, default_system_design_percent,\n      default_cc_fee_percent, default_misc_parts_percent,\n      cc_convenience_fee_enabled, cc_convenience_fee_type,\n      cc_convenience_fee_percentage, cc_convenience_fee_flat_amount,\n      cc_convenience_fee_label, commission_settings,\n      job_module_enabled, job_module_settings,\n      auto_clock_out_enabled, forgot_clock_out_penalty_points,\n      business_day_end_time, auto_clock_out_cutoff_time,\n      auto_clock_out_schedule_enabled, last_auto_clock_out_run,\n      require_gps_for_clock_in, require_gps_for_clock_out,\n      home_clock_notification_enabled, home_location_radius_meters,\n      home_clock_notification_roles, photo_upload_points,\n      on_my_way_sms_template, global_minimum_margin,\n      enforce_minimum_pricing, labor_rate_per_hour,\n      portal_proposals_enabled, portal_projects_enabled,\n      portal_appointments_enabled, portal_invoices_enabled,\n      portal_messages_enabled, portal_vip_services_enabled,\n      portal_punchlist_enabled, enable_public_vip_signup,\n      auto_completion_enabled, auto_completion_requires_approval,\n      auto_completion_reopen_on_delete,\n      auto_archive_declined_proposals_enabled,\n      auto_archive_declined_after_days\n    ) VALUES (\n      v_org_id, v_cs.company_name, 'electronic-life', v_cs.company_logo_url,\n      v_cs.website, v_cs.phone, v_cs.address,\n      v_cs.primary_contact_email, v_cs.portal_url,\n      COALESCE(v_cs.timezone, 'America/New_York'),\n      COALESCE(v_cs.currency, 'USD'),\n      v_cs.from_email, v_cs.from_name, v_cs.reply_to_email,\n      v_cs.default_tax_rate, v_cs.default_invoice_terms, v_cs.default_deposit_percent,\n      v_cs.default_project_mgmt_percent, v_cs.default_system_design_percent,\n      v_cs.default_cc_fee_percent, v_cs.default_misc_parts_percent,\n      v_cs.cc_convenience_fee_enabled, v_cs.cc_convenience_fee_type,\n      v_cs.cc_convenience_fee_percentage, v_cs.cc_convenience_fee_flat_amount,\n      v_cs.cc_convenience_fee_label, v_cs.commission_settings,\n      v_cs.job_module_enabled, v_cs.job_module_settings,\n      v_cs.auto_clock_out_enabled, v_cs.forgot_clock_out_penalty_points,\n      v_cs.business_day_end_time, v_cs.auto_clock_out_cutoff_time,\n      v_cs.auto_clock_out_schedule_enabled, v_cs.last_auto_clock_out_run,\n      v_cs.require_gps_for_clock_in, v_cs.require_gps_for_clock_out,\n      v_cs.home_clock_notification_enabled, v_cs.home_location_radius_meters,\n      v_cs.home_clock_notification_roles, v_cs.photo_upload_points,\n      v_cs.on_my_way_sms_template, v_cs.global_minimum_margin,\n      v_cs.enforce_minimum_pricing, v_cs.labor_rate_per_hour,\n      v_cs.portal_proposals_enabled, v_cs.portal_projects_enabled,\n      v_cs.portal_appointments_enabled, v_cs.portal_invoices_enabled,\n      v_cs.portal_messages_enabled, v_cs.portal_vip_services_enabled,\n      v_cs.portal_punchlist_enabled, v_cs.enable_public_vip_signup,\n      v_cs.auto_completion_enabled, v_cs.auto_completion_requires_approval,\n      v_cs.auto_completion_reopen_on_delete,\n      v_cs.auto_archive_declined_proposals_enabled,\n      v_cs.auto_archive_declined_after_days\n    )

\n\n    INSERT INTO organization_secrets (\n      organization_id,\n      qbo_connected, qbo_realm_id, qbo_access_token, qbo_refresh_token,\n      qbo_token_expires_at, qbo_payments_enabled,\n      twilio_account_sid, twilio_auth_token, twilio_phone_number,\n      google_maps_api_key, zip_tax_api_key, gemini_api_key, openai_api_key,\n      portal_io_connected, portal_io_access_token, portal_io_token_expires_at\n    ) VALUES (\n      v_org_id,\n      v_cs.qbo_connected, v_cs.qbo_realm_id, v_cs.qbo_access_token, v_cs.qbo_refresh_token,\n      v_cs.qbo_token_expires_at, v_cs.qbo_payments_enabled,\n      v_cs.twilio_account_sid, v_cs.twilio_auth_token, v_cs.twilio_phone_number,\n      v_cs.google_maps_api_key, v_cs.zip_tax_api_key, v_cs.gemini_api_key, v_cs.openai_api_key,\n      v_cs.portal_io_connected, v_cs.portal_io_access_token, v_cs.portal_io_token_expires_at\n    )

\n  END IF

\nEND $$

\n
